from __future__ import annotations

from datetime import datetime
from pathlib import Path
import base64
import shutil

ROOT = Path.cwd()

RESOLVER = ROOT / "lib/features/pedidos/domain/services/producto_pedido_resolver.dart"
PEDIDO = ROOT / "lib/features/pedidos/domain/entities/pedido.dart"
ADD_DIALOG = ROOT / "lib/features/pedidos/presentation/widgets/agregar_producto_dialog.dart"
STATE = ROOT / "lib/features/pedidos/presentation/bloc/pedidos_state.dart"
BLOC = ROOT / "lib/features/pedidos/presentation/bloc/pedidos_bloc.dart"
CONFIRM = ROOT / "lib/features/pedidos/presentation/widgets/confirmar_pedido_dialog.dart"
PAGE = ROOT / "lib/features/pedidos/presentation/pages/nuevo_pedido_page.dart"
BLOC_TEST = ROOT / "test/pedidos_bloc_test.dart"
ADD_TEST = ROOT / "test/agregar_producto_dialog_test.dart"


def decode(value: str) -> str:
    return base64.b64decode(value).decode("utf-8")


def fail(message: str) -> None:
    raise SystemExit(f"\nERROR: {message}\nNo se modificó ningún archivo.")


def replace_once(source: str, old: str, new: str, label: str) -> str:
    count = source.count(old)
    if count != 1:
        fail(
            f"No se pudo aplicar ‘{label}’. "
            f"Se esperaba 1 coincidencia y se encontraron {count}."
        )
    return source.replace(old, new, 1)


def replace_between(
    source: str,
    start_marker: str,
    end_marker: str,
    replacement: str,
    label: str,
) -> str:
    start_count = source.count(start_marker)
    end_count = source.count(end_marker)
    if start_count != 1 or end_count != 1:
        fail(
            f"No se pudo delimitar ‘{label}’. "
            f"Inicio={start_count}, fin={end_count}."
        )
    start = source.index(start_marker)
    end = source.index(end_marker, start)
    return source[:start] + replacement.rstrip() + "\n\n" + source[end:]


required = [PEDIDO, ADD_DIALOG, STATE, BLOC, CONFIRM, PAGE, BLOC_TEST]
for path in required:
    if not path.exists():
        fail(f"No se encontró {path.relative_to(ROOT)}")

if RESOLVER.exists():
    fail(f"Ya existe {RESOLVER.relative_to(ROOT)}")
if ADD_TEST.exists():
    fail(f"Ya existe {ADD_TEST.relative_to(ROOT)}")

pedido_source = PEDIDO.read_text(encoding="utf-8")
add_source = ADD_DIALOG.read_text(encoding="utf-8")
state_source = STATE.read_text(encoding="utf-8")
bloc_source = BLOC.read_text(encoding="utf-8")
confirm_source = CONFIRM.read_text(encoding="utf-8")
page_source = PAGE.read_text(encoding="utf-8")
bloc_test_source = BLOC_TEST.read_text(encoding="utf-8")

preconditions = [
    (PEDIDO, pedido_source, "class PresentacionPedidoOpcion extends Equatable"),
    (ADD_DIALOG, add_source, "List<_VariantePedidoUi> _variantes"),
    (STATE, state_source, "int get cantidadProductos =>"),
    (BLOC, bloc_source, "item.productoId == event.item.productoId"),
    (CONFIRM, confirm_source, "Widget _buildPasoProductos(PedidosState state)"),
    (PAGE, page_source, "class _CarritoBar extends StatelessWidget"),
    (BLOC_TEST, bloc_test_source, "no confirma un pedido sin dirección de cliente"),
]
for path, content, marker in preconditions:
    if marker not in content:
        fail(
            f"{path.relative_to(ROOT)} no contiene el marcador esperado: {marker}"
        )

new_resolver = decode('')
new_pedido = decode('')
new_add_dialog = decode('')
new_add_test = decode('')

state_updated = replace_once(
    state_source,
    decode(''),
    decode(''),
    "separar líneas y presentaciones",
)

bloc_updated = replace_between(
    bloc_source,
    "  void _agregarProducto(",
    "  void _eliminarItem(",
    decode(''),
    "lógica del carrito",
)

page_updated = replace_between(
    page_source,
    "class _CarritoBar extends StatelessWidget {",
    "class _SinHojaBanner extends StatelessWidget {",
    decode(''),
    "barra del carrito",
)

confirm_updated = replace_between(
    confirm_source,
    "  Widget _buildPasoProductos(PedidosState state) {",
    "  Widget _buildPasoCliente(PedidosState state) =>",
    decode(''),
    "productos del carrito",
)
confirm_updated = replace_between(
    confirm_updated,
    "  Widget _buildPasoConfirmacion(PedidosState state) {",
    "  Widget _acciones(PedidosState state) =>",
    decode(''),
    "confirmación del carrito",
)
confirm_updated = replace_between(
    confirm_updated,
    "  Widget _resumenProductos(PedidosState state) =>",
    "  Widget _title(String value) =>",
    decode(''),
    "resumen del carrito",
)

bloc_test_updated = replace_once(
    bloc_test_source,
    "  test('no confirma un pedido sin dirección de cliente', () async {\n",
    decode('')
    + "  test('no confirma un pedido sin dirección de cliente', () async {\n",
    "prueba de identidad del carrito",
)

updates = {
    RESOLVER: new_resolver,
    PEDIDO: new_pedido,
    ADD_DIALOG: new_add_dialog,
    STATE: state_updated,
    BLOC: bloc_updated,
    CONFIRM: confirm_updated,
    PAGE: page_updated,
    BLOC_TEST: bloc_test_updated,
    ADD_TEST: new_add_test,
}

for path, content in updates.items():
    if not content.strip():
        fail(f"El contenido resultante de {path.relative_to(ROOT)} está vacío.")

backup_dir = ROOT / (
    ".backup_selector_carrito_variantes_v1_"
    + datetime.now().strftime("%Y%m%d_%H%M%S")
)
backup_dir.mkdir(parents=True, exist_ok=False)

for path in updates:
    if path.exists():
        destination = backup_dir / path.relative_to(ROOT)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

for path, content in updates.items():
    existed = path.exists()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    print(f"{'Modificado' if existed else 'Creado'}: {path.relative_to(ROOT)}")

print(f"\nRespaldo: {backup_dir}")
print("\nSelector real de variantes y carrito corregidos.")
print("Esta fase todavía no modifica SQLite.")
